import numpy as np


def fit_power_law(N, L):
    x, y = np.log10(np.asarray(N, dtype=float)), np.log(np.asarray(L, dtype=float))
    slope = np.cov(x, y, bias=True)[0, 1] / np.var(x)
    intercept = y.mean() - slope * x.mean()
    return float(np.exp(intercept)), float(-slope)


